template <typename UnionPtrType>
ThemeInfoPtr ThemeInfo::Clone() const {
  switch (tag_) {
    case Tag::kChromeThemeId:
      return NewChromeThemeId(
          mojo::Clone(data_.chrome_theme_id));
    case Tag::kAutogeneratedThemeColors:
      return NewAutogeneratedThemeColors(
          mojo::Clone(*data_.autogenerated_theme_colors));
    case Tag::kThirdPartyThemeInfo:
      return NewThirdPartyThemeInfo(
          mojo::Clone(*data_.third_party_theme_info));
  }
  return nullptr;
}

template <typename T,
          typename std::enable_if<std::is_same<
              T, ThemeInfo>::value>::type*>
bool ThemeInfo::Equals(const T& other) const {
  if (tag_ != other.which())
    return false;

  switch (tag_) {
    case Tag::kChromeThemeId:
      return mojo::Equals(data_.chrome_theme_id, other.data_.chrome_theme_id);
    case Tag::kAutogeneratedThemeColors:
      return mojo::Equals(*(data_.autogenerated_theme_colors), *(other.data_.autogenerated_theme_colors));
    case Tag::kThirdPartyThemeInfo:
      return mojo::Equals(*(data_.third_party_theme_info), *(other.data_.third_party_theme_info));
  }

  return false;
}
